import { appendSplitCsv, copySplitFile, ensureSplitFolder, listSplitFolder, splitPath } from "~/core/persistence/splitFiles";

/**
 * gen3's `logData`, `logCopy` and `loadCsvFile` (the helpers above its component in
 * `scripts/frontend.js`), on the splits IPC instead of `require("fs")` (plan 2.4 /
 * 1.6). Generated by tools/port/lift-gen3.py, so every header string, path segment
 * and file-name template is byte-for-byte gen3's -- including its own `logCopy`,
 * which numbers a finished run by listing `finishes/` and copies nothing for a
 * test run (known-legacy-bugs.md #21).
 *
 * The legacy file also created `splits/`, `splits/Emerald` and `splits/FireRed` when
 * it loaded (and `storage/`, for the dead Storage.json object, which is not
 * reproduced), which is done here.
 */
for (const folder of ['', 'Emerald', 'FireRed']) {
    void ensureSplitFolder(folder);
}

