export async function logCopy(gameName, gameName_path, unique_run_identifier, starter, evolution, evolution_label, is_new_run, testStatus, loggedRunsManager) {
    if (evolution == true) {
        starter = evolution_label;
    }
    const testStatusText = testStatus ? "test_run_" : "";
    var dirPathAttempts = splitPath(gameName_path, starter, "attempts");
    var dirPathFinishes = splitPath(gameName_path, starter, "finishes");
    
    // Calculate the next finished_run_count by checking existing files in finishes folder
    let nextFinishedRunCount = 1;
    try {
        {
            // readdirSync over the splits IPC; a missing folder lists as empty, which is
            // what the existsSync guard made it.
            const files = await listSplitFolder(dirPathFinishes);
            // Look for files matching the pattern: ${gameName}-${starter}-${number}-simple.csv
            // (test runs are not copied to finishes, so we don't need to check for test_run_ prefix)
            const pattern = new RegExp(`^${gameName}-${starter}-(\\d+)-simple\\.csv$`);
            const numbers = files
                .map(file => {
                    const match = file.match(pattern);
                    return match ? parseInt(match[1], 10) : null;
                })
                .filter(num => num !== null);
            
            if (numbers.length > 0) {
                nextFinishedRunCount = Math.max(...numbers) + 1;
            }
        }
    } catch (error) {
        console.error('[logCopy] Error calculating next finished run count:', error);
    }
    
    await ensureSplitFolder(dirPathFinishes);
    // Copy files using unique_run_identifier from attempts folder and nextFinishedRunCount for finishes folder
    // Note: test runs are not copied to finishes folder
    if (!testStatus) {
        await Promise.all([
            copySplitFile(
                splitPath(dirPathAttempts, `${gameName}-${testStatusText}${starter}-${unique_run_identifier}-simple.csv`),
                splitPath(dirPathFinishes, `${gameName}-${starter}-${nextFinishedRunCount}-simple.csv`)),
            copySplitFile(
                splitPath(dirPathAttempts, `${gameName}-${testStatusText}${starter}-${unique_run_identifier}-full.csv`),
                splitPath(dirPathFinishes, `${gameName}-${starter}-${nextFinishedRunCount}-full.csv`)),
            copySplitFile(
                splitPath(dirPathAttempts, `${gameName}-${testStatusText}${starter}-${unique_run_identifier}.csv`),
                splitPath(dirPathFinishes, `${gameName}-${starter}-${nextFinishedRunCount}.csv`)),
        ]);
    }
}

/** The file picker behind "Load Splits": the File System Access API is Chromium's, not Node's. */
export async function loadCsvFile() {
    const file = await window.showOpenFilePicker({
        id: "SplitsFolder",
        types: [{
            description: "Split files",
            accept: { "text/csv": [".csv"] }
        }]
    });
    const contents = await file[0].getFile();
    const text = await contents.text();
    return text;
}
